CREATE TABLE public.vendor_appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), vendor_id text NOT NULL, message text NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 2000), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Accepted','Rejected')), response text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.vendor_appeals TO authenticated; GRANT ALL ON public.vendor_appeals TO service_role;
ALTER TABLE public.vendor_appeals ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_pending_vendor_appeal ON public.vendor_appeals(user_id) WHERE status='Pending';
CREATE POLICY "Own appeals or admin" ON public.vendor_appeals FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Restricted vendor appeal" ON public.vendor_appeals FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Pending' AND response='' AND NOT public.account_activity_allowed() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='vendor' AND vendor_id=vendor_appeals.vendor_id));
CREATE TABLE public.customer_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), target_type text NOT NULL CHECK(target_type IN ('product','shop')), target_id text NOT NULL, author_name text NOT NULL, author_photo text NOT NULL DEFAULT '', message text NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 2000), photos jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(photos)='array' AND jsonb_array_length(photos)<=3), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_feedback TO anon,authenticated; GRANT ALL ON public.customer_feedback TO service_role;
ALTER TABLE public.customer_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public feedback" ON public.customer_feedback FOR SELECT TO anon,authenticated USING(true);
CREATE OR REPLACE FUNCTION public.review_vendor_appeal(_id uuid,_status text,_response text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator required'; END IF; IF _status NOT IN ('Accepted','Rejected') OR length(trim(_response)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Decision and response required'; END IF; SELECT vendor_id INTO v FROM public.vendor_appeals WHERE id=_id AND status='Pending' FOR UPDATE; IF v IS NULL THEN RAISE EXCEPTION 'Pending appeal not found'; END IF; UPDATE public.vendor_appeals SET status=_status,response=trim(_response) WHERE id=_id; IF _status='Accepted' THEN UPDATE public.vendor_moderation SET status='Active',reason='',suspended_until=NULL,updated_by=auth.uid(),updated_at=now() WHERE vendor_id=v; END IF; END; $$;
REVOKE ALL ON FUNCTION public.review_vendor_appeal(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_vendor_appeal(uuid,text,text) TO authenticated;